INSERT INTO `coa_build_creator` (`entry`, `id`, `leveling_id`, `pve_id`, `pvp_id`, `class`, `author`, `name`, `subtext`, `description`, `icon`, `upvotes`, `created`, `updated`, `category`, `roles`, `primary_stat`, `flags`, `difficulty`) VALUES
(1, '418c479d-7270-495a-be3a-624ff209a553', '', '', '', 10, '艾罗', '弟弟', '', '### 概述\ntry frostseek :)', 'ability_ardenweald_paladin_autumn', 0, 1784819677, 1784819677, 1, 8, 0, 0, 0),
(2, 'ea6c9122-0afd-455c-8e67-dc3a0ff3eecb', '', '', '', 10, '娜妮卡', '大D', '', '### 概述\n超级无敌砰砰砰', 'ability_animusorbs', 0, 1784820027, 1784820027, 1, 8, 0, 0, 0),
(3, '13eae9c1-b724-40ad-9673-9e9cae5181d6', '', '', '', 10, '帕特', '跳舞熊', '', '### 概述\n在新手村的货车顶上跳舞！', 'ability_druid_denmother', 6, 1784821143, 1784821143, 1, 8, 0, 0, 0),
(4, '1bcd9bf4-bd4e-43ff-be28-78cc44c1995e', '', '', '', 10, '穆尔基', '肘击 - 混浊鱼人术士', '', '### 概述\n第 1 步：变成鱼人（抱鳍鱼人幻化、鱼人服装、重校准塔）\n第 2 步：做术士该做的事\n第 3 步：???\n第 4 步：获利\n\n核心在于跑赢敌人、疯狂上 DOT，并利用死亡骑士和暗影牧师的协同效果。', 'ability_creature_poison_01', 13, 1784821383, 1785607580, 1, 8, 3, 0, 0),
(5, 'dc1747ba-2c08-4bf6-a9d2-cc61744a726e', '', '', '', 10, '谢雷扎达', '熊坦', '', '### 概述\n专注于地下城升级的熊坦克升级构筑。\n\n### 优缺点\n优点：\n生存能力高\n\n缺点：\n伤害低\n\n### 输出循环\n无脑重殴和横扫。', 'ability_druid_protectorofthepack_mythic2', 0, 1784821552, 1784828509, 1, 2, 1, 0, 0),
(6, 'eacc87e5-df11-4d72-b92c-8c9544dd303d', '', '', '', 10, '塔莉埃拉', '初始升级：抢怪与输出', '', '### 概述\n似乎是当前拥挤环境下最容易升级并抢到怪物仇恨的构筑。\n\n### 优缺点\n技能方面有点杂乱。不知道它们是否能/会协同。未来可能会更新。', 'Interface\\Icons\\INV_Misc_QuestionMark', 1, 1784908014, 1784908014, 1, 8, 0, 0, 0),
(7, '91e8fa67-cc61-4296-9f34-51ea51322938', '', '', '', 10, '派珀', '诺甘农的选民', '', '### 概述\n施工中。狂怒先知构筑在 60 级时似乎被大幅削弱，因为需要太多圣骑士职业点数。无法再与牧师组合打出高额奥术/神圣伤害。\n\n已更新至 60 级，加入神圣启明。\n已为 S10 更新神秘附魔。\n\n### 优缺点\n优点：\n简单有效\n巨额伤害\n法力/生命自给自足\n入门门槛低（狂怒先知是唯一必需的秘术附魔）\n\n缺点：\n为了最优伤害大多必须站桩。\n极度专注于单体目标。\n48-59 级期间你几乎不会变强。\n\n### 装备\n优先级：\n\n*命中评级直到达标（17%）\n*急速直到软上限（1 秒 GCD）\n*法术强度（通用 > 奥术 > 神圣）\n*智力\n*暴击\n*精神\n*每 5 秒回蓝\n\n### 输出循环\n优先级：\n\n神圣启明（目标 100% 覆盖率）\n奥术强化\n唤醒（法力 < 30%）\n奥术飞弹（飞弹速射触发 + 减益层数 = 0 或 2 或 4）\n惩击（圣光涌动触发）\n奥术冲击（法力 > 30% + 减益层数 <= 4）\n\n神圣之火（神圣启明冷却好时）\n\n### 消耗品\n法术强度食物\n\n### 宏\n{HT}showtooltip\n/use 13\n/use 14\n/cast Divine Illumination\n\n将以上与其他不触发 GCD 的冷却技能结合使用\n\n### WEAKAURAS\n可结合法师、圣骑士和牧师的 WA 来追踪冷却、循环、增益等。\n\n推荐：\nNaowhUI = 饰品、自身增益、目标减益、职业资源、循环技能、冷却、实用工具', 'spell_holy_fanaticism', 6, 1784910067, 1784936837, 1, 8, 3, 0, 0),
(8, '20f08cc1-b2c4-47ca-b5b1-d5cbcbd3d2f8', '', '', '', 10, '哈布克', '构筑 0', '', '### 概述\n个人构筑\n\n### 优缺点\n23\n\n### 装备\n123\n\n### 输出循环\n123\n\n### 消耗品\n12313', 'ability_accretion', 1, 1784934506, 1784934506, 1, 8, 3, 0, 1),
(9, '96c7a4a5-2fcc-44c0-8189-e0cd0a691a5a', '', '', '', 10, '派珀', '唤魔师 S10', '', '### 概述\n施工中。易上手，精通也简单\n\n已更新至 60 级并加入嗜血\n增加了基础循环\n\n### 优缺点\n优点：\n由于触发的存在，机动性尚可\n\n缺点：\n在 4 个以上目标时相比其他构筑较弱\n\n### 装备\n命中（直到 17%）> 法术强度 > 智力 > 暴击（直到 33%）> 急速（直到嗜血下 1 秒 GCD）\n\n### 输出循环\n单体：\n无脑寒冰箭直到飞弹速射或冰冷思维触发\n在飞弹速射激活时使用奥术飞弹\n在冰冷思维激活时使用火球术\n在冰霜烈焰震击冷却好且冰冷思维激活时使用它\n在 5 个冰锥时使用冰枪术\n在冰霜之指激活或敌人已被冻结时，将冰枪术作为寒冰箭或奥术飞弹的碎裂连招的一部分使用\n\nAOE：\n前期只需无脑奥术爆炸\n后期你就能连锁寒冰箭了\n\n冷却：\n太多了……主要是嗜血 + 冰冷血脉来获得整整一分钟的急速增益\n奥术强化用来打大伤害。\n根据情况使用元素图腾\n\n### 消耗品\n优先级见装备部分', 'spell_fire_twilightrainoffire', 14, 1784960312, 1784970290, 1, 8, 3, 0, 0),
(10, '455da34b-2b63-4918-a042-40c843befcf6', '', '', '', 10, '史诗疯狂', '升级图腾/奉献 1-60 施工中', '', '### 概述\nAOE 升级构筑，非常适合法力风暴冲刺，希望你喜欢\n\n\n\n\n这是施工中的内容，如果你有任何建议或发现任何错误，欢迎私信/邮寄，我会修改\n\n### 优缺点\n巨额 AOE\n\n### 装备\n优先敏捷装备\n\n### 输出循环\n图腾 > 大地之力、岩浆图腾、法力之泉、风怒\n\n在第 2 和第 3 次召唤时放下岩浆图腾和灼热图腾，并在它们到期时重新施放\n\n使用虔诚光环、狂暴姿态、命令圣印、智慧祝福、火舌武器（确保对两把武器都施放）\n\n\n起手> 智慧审判> 召唤图腾> 烈焰震击> 奉献> 旋风斩> 雷霆一击> 毁灭打击\n\n之后无脑毁灭打击，直到旋风斩或雷霆一击冷却好\n\n### 备注\n玩得开心', 'ability_accretion', 7, 1785026756, 1785026948, 1, 8, 1, 0, 0),
(11, 'c6d214a4-9055-4892-b660-02e08815abcf', '', '', '', 10, '弗鲁米萨', '升级命中触发横扫猫', '', '### 概述\n这是我从 1 级到 40 级使用的构筑，简单高效。在法力风暴中我通常 AOE 和单体 DPS 都能进前 3。单刷任务时没有空档期，40 级前单体击杀大约 4-6 秒。虽然不算最优，但你可以轻松地两键无脑刷到 60 级并通关前期内容。你可以通过点出正义之怒然后无脑横扫来坦 5 人本。\n\n在首都召唤板附近的诺兹多姆处购买关键技能。\n============\n二元之道混合——你可能也可以纯敏捷玩。\n\n命中时协同\n- 前期 - 火舌武器；后期，毁灭术士的邪能灌注武器大约贡献你 40% 的伤害。它会从自动攻击和技能中触发。\n* 我还没试过圣化武器 + 命令圣印。它可能同样强甚至更强。\n* 我还没试过毒药，主要是因为不想在训练师费用上再花更多金币\n\n- 蛇形会增加你的自动攻击\n- 圣骑士圣印（先正义，后命令）会增加你的自动攻击\n- 如果你能在传家宝武器上找到便宜的火焰武器，那也不错。\n\n毒液喷吐 - 这是你 AOE 套装的另一半。当坦克停下移动时把它丢在地上。可能不值得用来单体输出。\n========\n\n切割 > 撕扯 > 撕咬，单体时无脑爪击/裂伤，多目标时横扫+毒液喷吐。\n\n穿敏捷和混合装备。如果有选择武器的余地，就用双手武器。\n\n使用你想要的任何元素变形。可能火最好，你可以尝试过渡到术士协同的火猫。\n\n对于史诗秘术附魔，可能是污染横扫或疯狂德鲁伊。我两个都还没拿到。\n\n后期等级优先能量，理想情况是你刚好能在每个 GCD 维持横扫，并且在施放喷吐时不会溢出。\n=========\n发布于 7 月 27 日。我可能会也可能不会更新此内容。就像我说的，这是为了升级临时拼凑的，你至少还能再挤出 10%。\n\n### 优缺点\n|cff1aff1a+不错的 AOE，不错的单体，简单循环|r\n- 有点无聊，手腕可能因为不停按而酸痛\n\n### 装备\n敏捷和混合装备。你通过猫/蛇形从敏捷获得攻强\n\n### 输出循环\n单体：切割 > 撕扯 > 凶猛撕咬，无脑爪击，有裂伤时用裂伤。我也保持撕扯。\n\nAOE：冷却好就毒液喷吐，无脑横扫，如果有连击点就保持切割。如果你在法力风暴中别忘了无脑喝药水，它能给你能量恢复。\n\n### WEAKAURAS\n如果你追踪清晰预兆，可能理想情况是用撕碎。老实说，我只是一直滚鼠标滚轮然后看另一个屏幕。', 'ability_mount_pinktiger', 0, 1785028152, 1785028152, 2, 8, 1, 0, 0),
(12, '2c92df8c-5291-4cb2-b54a-f58e1f73ae3d', '', '', '', 10, '戴维', '1', '', '### 概述\n1', 'INV_Misc_QuestionMark', 0, 1785030755, 1785030755, 1, 8, 0, 0, 0),
(13, 'b04fa416-852e-4ad2-8ecc-3b7a4e427fca', '', '', '', 10, '史诗疯狂', '图腾/奉献 灌注萨满', '', '### 概述\n非常有意思，尽情享受', 2, 1785049473, 1785049473, 2, 8, 1, 0, 0),
(14, '97df58e3-2567-452e-b4ab-038d250f7173', '', '', '', 10, '赞', '简单兽王猎', '', '### 概述\n无脑 0 秘术附魔兽王猎。可能不适合噩梦试炼。\n\n不需要秘术附魔（RE），只要塞入你觉得合适的即可。列出的 RE 只是推荐。\n\n2026/08/22 调整了天赋点\n\n特别说明：升级构筑有 bug，可能突然停止应用点数，甚至移除已设置的技能/点数。如果发生这种情况，有几种方法可以尝试修复。取消跟随构筑，/reload（或登出/登录），再次跟随构筑。或者先跟随另一个构筑再重新跟随这个构筑，但你会失去宠物。或者就继续升级，有时会自行修复。\n\n### 优缺点\n|cff1aff1a+ 简单|r\n+ 风险低\n\n- 没有秘术附魔就没有主动 AOE，除了狂乱之击\n- 在获得宠物之前，远程可能难以维持\n\n### 装备\n敏捷、耐力、攻强、暴击、智力\n\n我全部使用传家宝\n|cffe6cc80|Hitem:1339124:0:0:0:0:0:0:0:60|h[Champion Herod\'s Helmet]|h|r\n|cffe6cc80|Hitem:1339076:0:0:0:0:0:0:0:60|h[Pendant of the Warrior]|h|r\n|cffe6cc80|Hitem:1642950:0:0:0:0:0:0:0:60|h[Champion Herod\'s Shoulder]|h|r\n|cffe6cc80|Hitem:1339084:0:0:0:0:0:0:0:60|h[Champion\'s Deathdealer Cloak]|h|r\n|cffe6cc80|Hitem:1648677:0:0:0:0:0:0:0:60|h[Champion\'s Deathdealer Breastplate]|h|r\n|cffe6cc80|Hitem:1339110:0:0:0:0:0:0:0:60|h[Champion Herod\'s Bracers]|h|r\n|cffe6cc80|Hitem:1339131:0:0:0:0:0:0:0:60|h[Champion Herod\'s Gloves]|h|r\n|cffe6cc80|Hitem:1339096:0:0:0:0:0:0:0:60|h[Champion Herod\'s Belt]|h|r\n|cffe6cc80|Hitem:1339117:0:0:0:0:0:0:0:60|h[Champion Herod\'s Legguards]|h|r\n|cffe6cc80|Hitem:1339103:0:0:0:0:0:0:0:60|h[Champion Herod\'s Boots]|h|r\n|cffe6cc80|Hitem:1339082:0:0:0:0:0:0:0:60|h[Ring of the Lionhearted]|h|r x 2\n|cffe6cc80|Hitem:339075:0:0:0:0:0:0:0:60|h[Stick on a Carrot]|h|r - 可选\n|cffe6cc80|Hitem:1642991:0:0:0:0:0:0:0:60|h[Swift Hand of Justice]|h|r, |cffe6cc80|Hitem:1642992:0:0:0:0:0:0:0:60|h[Discerning Eye of the Beast]|h|r 直到你拥有足够的法力回复\n|cffe6cc80|Hitem:1642946:0:0:0:0:0:0:0:60|h[Charmed Ancient Bone Bow]|h|r\n2x |cffe6cc80|Hitem:1648716:0:0:0:0:0:0:0:60|h[Venerable Mass of McGowan]|h|r 或 |cffe6cc80|Hitem:1642944:0:0:0:0:0:0:0:60|h[Balanced Heartseeker]|h|r 或你拥有的任何暴击+敏捷+攻强武器\n\n### 输出循环\n治疗宠物（如需要）> 狂乱之击 > 倒刺射击，保持增益 > 稳固射击\n\n倒刺射击应尽量在快结束时使用，而不是冷却好就无脑按。这样你才能达到 3 层\n\n### 消耗品\n无需要\n\n### 宏\n为目标设置正确的追踪\n---\n/run local tt=UnitCreatureType("target") if tt then for i=1,GetNumTrackingTypes() do local n,_,a=GetTrackingInfo(i) if n and string.find(n,tt) then if not a then SetTracking(i) end break end end end\n---\n\n切换守护\n~~~\n{HT}showtooltip\n/castsequence !Aspect of the Hawk, !Aspect of the Viper\n---\n\n获取你悬停按钮的名称。用于替换以下宏中的 /click ElvUI_bar5Button1 和 2\n~~~\n/run print(GetMouseFocus():GetName().." ")\n---\n\n更新追踪（点击带有追踪宏的按钮），激活鹰守，并标记目标\n~~~\n{HT}showtooltip hunter\'s mark\n/click ElvUI_Bar5Button1\n/cast !Aspect of the Hawk\n/cast hunter\'s mark\n---\n\n每个攻击的示例。点击“每个冷却”按钮并使用技能。将神圣射击替换为你想搭配使用的技能，比如狂乱之击\n~~~\n{HT}showtooltip\n/click ElvUI_Bar5Button2\n/cast Holy Shot\n---\n\n使用你所有冷却。升级时我们其实不在乎等它们。同时也控制你的宠物\n~~~\n{HT}showtooltip Blood Fury(Racial)\n/startattack [combat]\n/stopattack [nocombat]\n/cast [combat] Blood Fury(Racial)\n/cast [combat] Bestial Wrath\n/cast [combat] Rapid Fire\n/cast [combat] Kill Command\n/cast [combat] Unrelenting Wrath\n/petattack\n/petpassive [nocombat]\n/petdefensive\n---\n\n用鼠标左/右键给武器附魔\n~~~\n{HT}showtooltips\n/cast [@none, button:1] Rockbiter Weapon; [@none] Rockbiter Weapon\n/use [button:1] 16; 17\n/click StaticPopup1Button1 \n---\n\n### WEAKAURAS\n无需\n\n### 备注\n尽量带坚韧系宠物。熊、乌龟、大猩猩等。可在此找到列表 https://db.ascension.gg/?pets=1\n\n狼最终也能保持仇恨，即使不嘲讽。我认为它略优于奇美拉、魔暴龙和迅猛龙。', 'ability_earthen_hyperproductive', 16, 1785061324, 1787463135, 1, 8, 1, 0, 0),
(15, '18bbe2b4-0e4a-44c2-8541-0a761bd628ae', '', '', '', 10, '禁止无趣', '请给15级', '', '### 概述\n圣骑士 + 萨满混合，全类型驱散诅咒\n宠物 + 魔杖到 10 级然后法力风暴，或使用不同专精直到可以进行 MS/RDF', 'ability_warlock_jinx', 1, 1785069291, 1785075873, 1, 4, 4, 0, 0),
(16, '05add9af-94ee-4094-b091-f9afcb79c102', '', '', '', 10, '伊杜姆', '伊杜姆的火焰贤者', '', '### 概述\n“以火焰净化”，至少你的伤口能被净化。\n在找一个治疗构筑，像治疗但又感觉略有不同。\n试试我的火焰贤者构筑，新手易学，老手有趣。\n这可能会让你感觉像生命缚誓者阿莱克丝塔萨。\n\n\n优秀的直接治疗者，对 AOE 治疗关注较少。\n使用火焰和神圣法术治疗，如果其中一个被打断，另一个元素仍然可用。\n\n可以驯服龙并提供龙之知识增益。\n推荐龙类\n翡翠 -> 治疗 +\n红宝石 -> 暴击 +（更高触发几率）\n蓝宝石 -> 法力回复\n\n### 优缺点\n|cff1aff1a+可以同时 DPS 和治疗|r\n+ 无消耗的瞬发治疗触发\n\n- 法力消耗快，控制你的法力回复\n- DPS 需要命中评级\n\n### 装备\n法术强度（治疗）-> 暴击评级 -> 急速评级 -> 精神 -> 命中评级\n\n### 输出循环\n灼烧之焰是你的基础治疗，用于中等治疗\n小额持续治疗使用恢复\n尽量保持烈焰打击以触发大量效果\n圣光闪现用于圣光涌动触发时的无消耗瞬发治疗\n神圣之星和愈合之环是你的 AOE 治疗\n\n火球术仍用于伤害，比灼烧之焰打得更痛。\n龙息，用于 AOE 锥形攻击，也让你的下一次烈焰打击瞬发。\n热 streak 触发时使用炎爆术，炎爆术也会 AOE 治疗\n\n控制法力，经常使用光辉光环，法力低于 30% 时使用唤醒。\n\n### 宏\n火球术最大\n{HT}showtooltip\n/cast [harm] Fireball\n/cast [noharm] Cauterizing Fire', 'ability_evoker_terroroftheskies', 6, 1785079403, 1785887520, 1, 4, 4, 0, 1),
(17, '0c7df239-cc3c-42e6-9b46-644284014a0b', '', '', '', 10, '富特瓦丹齐格', '熔岩战斗法师', '', '### 概述\n作为双持烈焰战斗法师燃烧世界。一个简单的升级构筑，你可以在 20 级左右拥有大部分功能，优先获取宏部分展示的技能。\n这个构筑可以轻松适应你喜欢的任何元素伤害类型，并用你其他喜爱的技能强化，所以你可以把它当作基础构筑来改造。在 32 级时创建了这个帖子。抱歉没有逐级细致管理，那看起来太繁琐了，我相信你。\n\n### 优缺点\n交替的资源再生“阶段”让你不太会因为任何一种资源而挣扎。我经常有足够的资源可以甩出一些治疗法术来辅助主治疗。-点燃确实会覆盖自己，如果你覆盖了你的熔岩爆裂暴击那就很遗憾，但无所谓。\n\n### 装备\n暴击、力量、智力和双持以获得更多战斗法师触发。\n\n### 输出循环\n非常简单的循环，因为我的手很痛。\n(1) 无脑按你的烈焰震击宏生成怒气\n(2) 用熔岩猛击宏消耗它，并用熔岩爆裂收尾造成大伤害\n(2b) 确保你的目标仍受烈焰震击影响以打出瞬发暴击。\n(2c) 如果你需要更多怒气，继续按你的熔岩爆裂宏（火球术）。\n(3) 在 AOE 中保持熔岩猛击宏冷却好就按，通常只用烈焰打击作为起手因为它非常耗蓝。\n\n即使是单体我也更喜欢顺劈斩而不是英勇打击，为了简单，同时熔岩爆裂和毁灭打击也提供了足够的单体伤害。\n\n### 宏\n(1)**瞬发远程攻击\n{HT}showtooltip Flame Shock\n/startattack\n/castsequence reset=6 Flame Shock, Fire Blast\n\n(2)**近战攻击\n{HT}showtooltip Lava Lash\n/startattack\n/cast Flamebound Cleave\n/castsequence reset=6 Lava Lash, Flare Breaker, Flare Breaker\n\n(2)**施法远程攻击\n/castsequence reset=8 Lava Burst, Fireball, Fireball\n\n**AOE 雷霆一击(熔岩猛击)\n{HT}showtooltip Lava Smash\n/castsequence reset=6 Lava Smash, Whirling Flames\n\n### 备注\n获取 MiK 战斗滚动条并调整它只显示暴击的数字，因为其他数字都不重要，对吧。我不是构筑大师，但我用这个取得了不错的成绩。', 'ability_rhyolith_volcano', 0, 1785096598, 1785096598, 1, 8, 0, 0, 0),
(18, '966f9655-c7ea-4002-9296-c9376f15bcb4', '', '', '', 10, '战鹰', '暗影精通', '', '### 概述\n术士和暗影牧师协同，追求最大暗影施法者伤害\n\n### 优缺点\n优点 - 单人、组队或法力风暴都非常好。高伤害。浆果能坦，小鬼对团队很棒\n\n\n缺点 - PvP 玻璃大炮\n\n### 装备\n忽略我秘术附魔的初始构筑，那是我当时仅有的', 'ability_priest_auspiciousspirits', 2, 1785119887, 1785119903, 2, 8, 3, 0, 0),
(19, '2960b63b-dee2-43bb-8462-648d7df09e17', '', '', '', 10, '提拉纳斯特罗斯', '已更新 - 提尔的双持凛冬之风冰霜', '', '### 概述\n已更新 - 现在这是一个双持冰霜死亡骑士构筑。\n已单独制作了双手切割与冰霜 + 凛冬之风构筑。\n从盗贼 + 法师开始，在获得冰霜之指 + 碎裂天赋后转向冰霜死亡骑士。\n\n测试后：\n不幸的是，切割与冰霜（秘术附魔）需要一把双手武器才能生效/使用。然而，冰霜死亡骑士的大部分意义在于双持并用强力的副手攻击强化湮灭伤害。\n这个版本的构筑专注于作为双持冰霜盗贼 + 死亡骑士，一个升级冰霜死亡骑士 + 冰霜法师（为了冰霜之指 + 碎裂伤害）\n\n注意：由于第 10 赛季的限制，完整的冰霜死亡骑士工具箱来得相当晚。你大部分时间将作为一个冰霜主题的双持盗贼，用邪恶攻击/霜击积攒连击点，用凛冬之风消耗。死亡骑士技能主要是在能量恢复时作为填充。\n\n### 备注\n这个构筑从凛冬之风盗贼开始。你将使用霜击 + 凛冬之风作为核心循环，并使用死亡骑士法术作为填充，同时将冰霜束缚顺劈斩宏到你的主要攻击循环中。\n\n由于强调冰霜之指 + 碎裂的凛冬之风，完整的死亡骑士工具箱来得相当晚。\n\n在双武器上使用燃烬冰川符文。目标是让燃烬冰川效果在目标身上保持最大覆盖率，使其受到的冰霜伤害提高 20%。\n\n满级时，霜击 + 凛冬之风连招仍然是你的核心游戏循环。死亡骑士技能主要作为能量恢复时的填充。', 'Spell_Frost_FrostArmor', 3, 1785123754, 1786466711, 1, 8, 1, 0, 1),
(20, 'aaea6160-83d3-4080-978a-41909f0dc7d4', '', '', '', 10, '至日', '日落', '', '### 概述\n只是一个实验！将平衡德鲁伊 + 射击猎人结合，配上一套火热的秘术附魔。此时可能仍有点施工中', 'ability_paladin_toweroflight', 0, 1785125370, 1785125721, 1, 8, 3, 0, 0),
(21, '152a07ca-eb61-409b-a8c8-ede94b7e45a3', '', '', '', 10, '塞拉西斯', '布利奇', '', '### 概述\n布利奇', 'Ability_Rogue_Rupture', 2, 1785143709, 1785143709, 2, 8, 1, 0, 0),
(22, '05bbeb85-051a-482a-b8c3-4e00284de913', '', '', '', 10, '哈莫尼', '你大概不该用这个', '', '### 概述\n明显未完成', 'Interface\\Icons\\INV_Misc_QuestionMark', 0, 1785150720, 1785150720, 1, 8, 0, 0, 0),
(23, 'c73c0053-4d37-45fb-91fa-64dcfc713e31', '', '', '', 10, '奥伊', '奥伊 - 萨满真言术：盾 团本/大秘境', '', '### 概述\n真言术：盾刷子回来了兄弟们\n驯服一只水元素\n\n### 装备\n双持以使用 2 个武器附魔 + 2 个大地生命武器\n法术强度 > 每 5 秒回蓝 > 智力/急速/暴击', 'ability_dragonriding_swapflightstyles01', 2, 1785162157, 1785972017, 2, 4, 4, 0, 1),
(24, 'aaf370e5-fa02-4a02-abee-01cc4058aace', '', '', '', 10, '伊杜姆', '伊杜姆的森林守望者', '', '### 概述\n在 Area 52 上非常流行的构筑，这里稍作改动。\n森林守望者更侧重于射击，并在这里很好地用图腾辅助。\n同样的感觉，略有不同。\n提醒各位，这个构筑在低等级时需要大量初始秘术附魔，如丛林射击、医疗之刺和绽放射击，以及 10 级时的丛林医药。\n低等级时治疗更难，但并非不可能，真正开始是在 35 级，当你装备丛林游侠敏捷时。\n\n### 优缺点\n|cff1aff1a+DPS= 治疗，而且还不差。|r\n+技能消耗更少法力\n+也适合单人升级\n\n-真正的部分从 35 级丛林游侠敏捷开始\n-需要最小 5 码范围\n-装备是双份。\n\n### 装备\n秘术附魔顺序\n---------------------------\n史诗：丛林游侠的敏捷 -> 丛林游侠 -> 希波克拉底誓言 -> 狂乱生长\n稀有：医疗之刺 -> 丛林射击 -> 绽放射击 -> 退潮图腾 -> 森林之灵\n免费：丛林医药 -> 毒蛇钉刺雕文 -> 稳固射击雕文 -> 大地生命武器雕文 -> 野性成长雕文 -> 宁静\n\n属性顺序\n--------------\n1-35 级\n-----------\n法术强度 -> 智力 -> 暴击评级\n\n35+ 级\n---------\n命中评级 14%（-1% 英雄灵气）-> 敏捷 => 攻击强度 => 法术强度 -> 智力 -> 暴击评级 -> 每 5 秒回蓝\n\n### 输出循环\n用医疗之刺影响你的目标，这将治疗目标附近的盟友，并随机影响一名玩家施放丛林医药，也会持续治疗。\n在带有医疗之刺的目标上经常使用奇美拉射击，这会触发医疗脉冲治疗 5 名受伤最重的队员。\n绽放射击用于大拉或快速治疗，但最好在你拥有自然之力增益时使用，将绽放射击效果提高 400%，使用绽放射击后大约需要 16 秒，但其他远程武器技能会降低冷却。\n学会丛林游侠后，你的猎人射击会为其叠层，每层将治疗之触的施法时间和法力消耗降低 50%，适合坦克倒下时快速治疗，否则用野性成长消耗它来为队伍提供增益。\n法力不足时，使用激活，如果还不够，你可以切换到蝰蛇守护来生成法力。\n此外森林守望者也是一个完美的毒药驱散者，用废除毒药，适合驱散削减治疗的毒药效果。\n\n### 宏\n丛林射击\n\n{HT}showtooltip\n/cast [noharm] Grove Shot\n/cast [harm] Steady Shot\n\n### 备注\n使用丛林射击时要小心。\n这可能会激活自动攻击，使用丛林射击会自动选中一个敌人，所以不要无脑按那个技能。\n这可能是因为标准技能来自稳固射击，可能会认为它是一次远程武器攻击。', 'ability_druid_naturalperfection', 11, 1785166409, 1787706864, 1, 4, 4, 0, 2),
(25, '477db7b1-768a-435e-86a5-ce35c724dc73', '', '', '', 10, '芬茨', '芬茨的熊', '', '### 优缺点\nawd\n\n### 装备\nadw\n\n### 输出循环\nawd\n\n### 消耗品\nawd', 'ability_accretion', 2, 1785186929, 1785186929, 2, 8, 1, 0, 0);
INSERT INTO `coa_build_creator` (`entry`, `id`, `leveling_id`, `pve_id`, `pvp_id`, `class`, `author`, `name`, `subtext`, `description`, `icon`, `upvotes`, `created`, `updated`, `category`, `roles`, `primary_stat`, `flags`, `difficulty`) VALUES
(26, '392a3b4f-13dc-49fd-b349-b474359e5b3d', '', '', '', 10, '提拉纳斯特罗斯', '风暴震击萨满', '', '### 概述\n增强萨满 AOE 构筑。\n需要少量秘术附魔才能完全发挥作用。\n\n### 优缺点\n优点：\n+AOE 高\n+单体尚可\n+总有技能可以按\n+ 借助冲锋 + 疾跑有一定机动性\n+ 借助闪避 + 恢复有一定防御能力\n\n缺点：\n-耗蓝严重\n\n### 装备\n二元之道。\n使用可获得的最佳敏捷或智力、攻击强度/法术强度装备。它们都能提升你的技能。\n\n目标是地下城/团本的命中上限和精准上限。\n\n精准（达标）> 命中（法术上限）> 敏捷 = 智力 = 攻击强度 = 法术强度 > 暴击几率 > 急速\n\n### 输出循环\n使用漩涡武器层数用于：\n地震术、\n闪电链\n\n单体：\n消耗漩涡层数\n风暴打击\n熔岩猛击 / 闪电猛击\n大地震击\n伏特打击 x3\n消耗连击点\n\nAOE：\n消耗漩涡层数\n震击\n裂地\n伏特打击 x3\n凛冬之风\n\n连击点使用：\nAOE 使用凛冬之风\n保持切割\n恢复用于自我治疗\n冥想用于法力回复\n\n### 宏\n萨满一键：\n{HT}showtooltip\n/castsequence reset=combat/8 Stormstrike, Lightning Lash, Earth Shock\n/cast Cleave\n/startattack\n\n连击点一键：\n{HT}showtooltip\n/castsequence reset=combat Volt Strike, Volt Strike, Volt Strike, Winds of Winter, Volt Strike, Volt Strike, Volt Strike, Slice and Dice\n/cast Cleave\n\n光标位置施放地震术：\n{HT}showtooltip\n/cast [@cursor] Earthquake', 'ability_thunderking_overcharge', 0, 1785195843, 1785195843, 2, 8, 1, 0, 1),
(27, '396665c6-e101-465c-a550-b4eb96b6b7a3', '', '', '', 10, '风', '死亡圣骑士', '', '### 概述\n备注', 'ability_paladin_beaconsoflight_blue', 9, 1785203191, 1785203191, 1, 2, 0, 0, 0),
(28, '8eef3cad-249a-4ab2-a111-509496238bad', '', '', '', 10, '提拉纳斯特罗斯', '超坦战争死亡骑士融合坦克', '', '### 概述\n一个完全以防御为导向的战士 + 死亡骑士坦克构筑，用于团队内容升级。\n早期点出死亡骑士技能和天赋，然后在 32 级转向战士以获得格挡。\n在防御姿态下坦克，同时从鲜血灵气中获得一些自我治疗。\n\n不需要秘术附魔。\n\n测试结果：\n个人认为，手感不太好。它过于偏向防御，并且因为专注于使用盾牌而失去了死亡骑士技能的伤害潜力。感觉其他构筑也能做到同样的事，但更好。', 'ability_argus_edgeofobliteration', 1, 1785209957, 1785446575, 1, 8, 0, 0, 1),
(29, '22ad9630-7f01-4c41-8c5b-3b4d1bde6070', '', '', '', 10, '温特', '冰封迷失 - 死亡骑士猎人', '', '### 概述\n你被派往诺森德远征，却再也没能回家。你的家人为你的命运哀悼，但没有哪个当局真的费心去寻找像你这样无价值的士兵。失血过多并被冰封，当你和你心爱的同伴回来时，你已变成了别的东西。\n\n这个构筑仍在测试中，可能会迭代/它是施工中的！', 'spell_deathknight_festering_strike', 0, 1785229678, 1785229809, 1, 8, 1, 0, 0),
(30, 'e1dcff1f-b1aa-444a-a00e-2d25391f31c3', '', '', '', 10, '维里塔斯', '阿波罗之箭', '', '### 概述\n太阳游侠，将光明与火焰降临于那些应得正义之人。\n\n### 备注\n开始制作光明游侠构筑。可能是二元之道。', 'Ability_Hunter_ExplosiveShot', 0, 1785243833, 1787689048, 1, 8, 1, 0, 0),
(31, 'b1f54591-7b57-44e8-adc2-febba77849c9', '', '', '', 10, '梅伦迪亚', '史诗地下城神圣治疗', '', '### 概述\n施工中，可以很好地打史诗+地下城。愈合之环只是为了增加范围，主要 AOE 治疗是神圣新星和超级新星。COA 技能非常强大，神圣超级新星非常强大，是你在拉怪时睡着时的应急按钮。\n\n8 个开放点数用于情境技能，如解毒或群体驱散等。', 'ability_paladin_veneration', 3, 1785253694, 1785253694, 2, 4, 4, 0, 0),
(32, '9f76568f-d508-4749-81c6-659a71161e5e', '', '', '', 10, '红三叶草', 'a', '', '### 概述\na\n\n### 优缺点\na\n\n### 装备\na\n\n### 输出循环\na\n\n### 消耗品\na\n\n### 宏\na', 'ability_bastion_demonhunter', 0, 1785255332, 1785255355, 2, 8, 3, 0, 0),
(33, '7b3a362a-d949-4b29-9b8f-f19d7ff6751f', '', '', '', 10, '莉莉吉', '丛林游侠', '', '### 概述\n又一个丛林游侠 FPS+治疗', 'Ability_Hunter_ZenArchery', 0, 1785260166, 1785260166, 2, 8, 4, 0, 0),
(34, '9e59348c-2ad6-4e25-9957-d86c51f1cd6e', '', '', '', 10, '梅伦迪亚', 'glrog', '', '### 概述\n双持', 'ability_bastion_deathknight', 0, 1785271104, 1785271104, 2, 8, 4, 0, 0),
(35, 'f0d0d8be-4c56-47e5-916b-4989d82257ae', '', '', '', 10, '牛肉法师', '风怒战士萨满', '', '### 概述\n萨满战士', 'Ability_Ambush', 0, 1785274335, 1785274335, 2, 8, 1, 0, 0),
(36, 'c6dd82c6-5b1d-464e-8065-b45a1c4164af', '', '', '', 10, '提拉纳斯特罗斯', '提尔的 AOE 超载纵火狂', '', '### 概述\n为法力风暴升级火焰 AOE 起草的构筑。法师 + 术士的经典融合。\n虽然基于火焰，但也旨在利用冰霜之指 + 碎裂天赋发挥超级法术暴击。\n\n影响玩法的秘术附魔：\n烈焰爆发 - 一个瞬发的烈焰打击（除非在清晰施法下施放，否则会燃烧法力）\n火焰风暴 - 使术士的火焰之雨变为施法而非引导。\n德拉卡脆皮 - 将龙息转变为毁灭性的飞越轰炸。在大拉时造成惊人伤害。建议准备好闪现以返回原点。\n精准冲击 - 可以触发以允许背靠背施放陨石术。\n\n在较低等级（16 到 36）时，你主要会施放烈焰打击并引导火焰之雨\n• 有了秘术附魔，它会在清晰施法触发时施放瞬发烈焰爆发，并施放火焰风暴，然后引导暴风雪，叠加 3 层 AOE 效果！\n\n36 级时，你将能够开始投下陨石并使用德拉卡脆皮进行飞越轰炸。\n你将逐渐解锁更多 AOE。\n• 冰锥术\n• 冰霜宝珠\n• 暗影烈焰\n• 古尔丹之手\n\n法力风暴冲刺随着你升级会变成 AOE 循环管理。\n冰锥术或冰霜宝珠触发冰霜之指以碎裂。\n德拉卡脆皮造成巨额 AOE 暴击伤害\n背靠背投下陨石\n在清晰施法下保持烈焰爆发\n等等', 'ability_evoker_oppressingroar2', 4, 1785276610, 1786512302, 1, 8, 3, 0, 2),
(37, 'c556625e-b5f1-40a9-b545-2bcaef883350', '', '', '', 10, '山羊看', '超级治疗 - 已更新', '', '### 优缺点\n可用于法力风暴/地下城和开放世界\n你将拥有单体治疗和 AOE 治疗。\n你将比大多数 DPS 造成更多 AOE 伤害。\n\n优先级 = 智力/法术强度> 急速>暴击>每 5 秒回蓝\n\n一些灵活点数可根据你的喜好调整此构筑。\n\n如果你有问题给我发消息，我很乐意回答。\n\n### 装备\n6 件虔诚 |cffa335ee|Hitem:243684:0:0:0:0:0:0:0:60|h[Devout Crown]|h|r\n|cffa335ee|Hitem:222268:0:0:0:0:0:0:0:60|h[Draconic Infused Emblem]|h|r|cffa335ee|Hitem:241834:0:0:0:0:0:0:0:60|h[Witching Hourglass]|h|r\n1 主手 1 副手\n\n### 输出循环\n始终让坦克拥有圣光道标/圣光庇护\nAOE = 黑暗输血、神圣新星、神圣超级新星、光明之锤\n单体 - 圣光闪现 -> 神圣震击', 'ability_priest_flashoflight', 3, 1785282411, 1785610488, 1, 4, 4, 0, 1),
(38, 'eb603ab9-992f-4c1e-b0e5-80146b44ffee', '', '', '', 10, '塞拉西斯', '火舌匕首构筑(附点燃)', '', '### 概述\n我不知道这好不好用，但无所谓，升级时很有趣，熔岩爆裂在 50 年代中期前一击必杀。\n你驯服的龙类弄一只红色的，格瑞姆巴托入口附近有雏龙和龙人，而且我知道奥特兰克至少有一只稀有的龙可以驯服，所以祝你好运。不是最优，所以别 @ 我，我只是随便做做', 'Spell_Fire_Fireball02', 0, 1785283237, 1785979422, 2, 8, 1, 0, 0),
(39, '73691b42-4076-40e3-92aa-ee9a1ec0c9d0', '', '', '', 10, '神圣滚轮', '食尸鬼猎人', '', '### 概述\n。', 'ability_creature_disease_02', 0, 1785283521, 1785283521, 2, 8, 1, 0, 1),
(40, '9b67fd2a-c87b-4f16-89bb-b8b2f7d1b91a', '', '', '', 10, '科莫多', '黑暗神化 - 火焰兵工厂坦克', '', '### 概述\n它就是能用\n\n### 输出循环\n技能亮了就按。简单', 'ability_demonhunter_torment', 2, 1785290857, 1785290857, 2, 8, 3, 0, 0),
(41, 'ce24c7dc-4e02-41df-8aef-70783b8e11af', '', '', '', 10, '莱克索', '莱克测试风暴之子', '', '### 概述\n。', 'ability_argus_soulburst', 0, 1785336118, 1785336118, 1, 8, 0, 0, 0),
(42, '0db67aa0-ed49-4b49-9853-84a1150eb830', '', '', '', 10, '塞莱斯托斯', '兽王猎人 pve (兽王猎)', '', '### 概述\n经典兽王猎，你依赖快速稳固射击来持续刷新你最好的狂野怒火，它会重置你的狂乱射击，也有不错的 AOE。这是团本首领战首选构筑，但大秘境不太行', 'Ability_Druid_SkinTeeth', 0, 1785340467, 1785340467, 2, 8, 1, 0, 0),
(43, '1e1f1ca2-30fe-4a3d-bc68-0077d4ed8082', '', '', '', 10, '阿亚梅', '测试1', '', '### 概述\nasas', 'spell_frost_frostbolt02', 0, 1785349794, 1785349794, 2, 8, 3, 0, 0),
(44, '2a812299-3c39-47af-bdbb-2b9dd4d83d8f', '', '', '', 10, '提拉纳斯特罗斯', '闪电链 AOE 刷子', '', '### 概述\n为法力风暴升级制作的构筑，利用闪电双击和分叉闪电秘术附魔在法力风暴升级中实现高 AOE 输出。\n\n涉猎法师以获得一些法力资源，并在后期等级涉猎圣骑士以获得实用技能和增益。\n\n添加一些无职业或 COA 秘术附魔以获得额外 AOE 输出。例如：\n• 暗影炮击\n• 辛达苟萨之息\n• 亡者行军\n• 绝对零度\n• 导管\n\n### 优缺点\n|cff1aff1a+高 AOE 输出|r\n+尚可的单体输出\n+增益和实用技能\n+法力回复以抵消高法力消耗\n\n-单人升级时仍可能耗尽法力\n-最好在队伍中使用\n\n### 装备\n传家宝：\n神秘元素装备\n|cffe6cc80|Hitem:1339123:0:0:0:0:0:0:0:60|h[Mystical Helm of Elements]|h|r\n\n法术强度饰品：\n|cffe6cc80|Hitem:1339077:0:0:0:0:0:0:0:60|h[Pendant of the Sorcerer]|h|r\n|cffe6cc80|Hitem:1339083:0:0:0:0:0:0:0:60|h[Ring of the Seer]|h|r\n|cffe6cc80|Hitem:1642992:0:0:0:0:0:0:0:60|h[Discerning Eye of the Beast]|h|r\n\n### 输出循环\n单体：\n• 烈焰震击 > 熔岩爆裂 > 闪电箭\n\n基础 AOE：\n• 地震术 > 闪电链\n\n如果你有其他可用的秘术附魔技能也加以利用。', 'ability_siege_engineer_magnetic_lasso', 8, 1785351362, 1785446143, 1, 8, 3, 0, 0),
(45, 'ee169d57-b884-4657-a147-7ca30b560401', '', '', '', 10, '利耶雷', '瘟疫使者', '', '### 概述\n瘟疫使者构筑的近战变体。为了我的名望重置目的。\n\n目前我们将使用二元之道。\n\n施工中。', 'ability_deathknight_roilingblood', 1, 1785352475, 1785353036, 1, 8, 3, 0, 0),
(46, 'cac04950-5c76-4ae9-80ed-c81553578d08', '', '', '', 10, '哈莫尼', '最能坦的熊', '', '### 概述\n简单、免费、就是熊。\n\n这个赛季仇恨不是问题，所以你只要当一堵墙就行。\n\n### 优缺点\n|cff1aff1a+你将玩过的最简单的坦克|r\n\n-治疗会忘记治疗你的恶魔\n\n### 装备\n皮甲闪避护甲熊配盾牌敏捷暴击熊\n\n### 输出循环\n对首领的实用技能维持：对首领保持雷肤术，对目标保持至少 1 层裂伤，对目标保持精灵之火或掘地虫酸液，对目标保持 5 层破甲（破魂），对目标保持虫群（精灵之火（野性））。对目标保持狂犬病（裂伤（熊））\n\nAOE：裂伤、痛击、掘地虫酸液、横扫\n\n始终：重殴\n\n### 消耗品\n坦克物品\n\n### 宏\n你真的可以按住这个宏对付一切并且没事：\n{HT}showtooltip\n/startattack\n/castsequence reset=combat mangle (bear), thrash (bear), lacerate, sunder soul, faerie fire (feral)\n/cast maul\n/cast enrage\n/cancelaura enrage\n\n懒人 AOE：\n{HT}showtooltip\n/startattack\n/castsequence reset=combat thrash (bear), earthborer acid, swipe (bear), swipe (bear), swipe (bear)\n/cast maul\n/cast enrage\n/cancelaura enrage\n\n### WEAKAURAS\n施工中\n\n### 备注\ndiscord{HT}dumedag 如果我不在线就在那给我发消息', 'ability_racial_cannibalize', 5, 1785361771, 1785584662, 2, 2, 1, 0, 0),
(47, '3b7e1847-55f0-4702-89b8-418e8b1fcee3', '', '', '', 10, '德莫克斯', 'Yurp', '', '### 概述\n嗨', 'Interface\\Icons\\INV_Misc_QuestionMark', 0, 1785368718, 1785368718, 2, 8, 0, 0, 0),
(48, '5d04fca0-8b5d-4c09-a51d-c56a76a6ceb4', '', '', '', 10, '克罗里格斯', '泰坦之握元素能量战士', '', '### 概述\n第一个构筑', 'ability_racial_fireblood', 0, 1785372405, 1785372405, 2, 8, 0, 0, 0),
(49, '3af5634f-f860-4700-88bb-72c11812ff18', '', '', '', 10, '希尔丝', '希尔丝的构筑', '', '### 概述\n84', 'Interface\\Icons\\INV_Misc_QuestionMark', 0, 1785377783, 1785377783, 2, 8, 0, 0, 0),
(50, 'd05a4c7d-72d6-400c-b644-85034de7d1e1', '', '', '', 10, '比缪斯德', '恢复德鲁伊升级', '', '### 概述\n我已经试图制作这个构筑十亿小时了。这东西太坏了。>:( 施工中', 'ability_druid_treeoflife', 0, 1785388985, 1785388985, 1, 4, 4, 0, 0);
INSERT INTO `coa_build_creator` (`entry`, `id`, `leveling_id`, `pve_id`, `pvp_id`, `class`, `author`, `name`, `subtext`, `description`, `icon`, `upvotes`, `created`, `updated`, `category`, `roles`, `primary_stat`, `flags`, `difficulty`) VALUES
(51, '310f3054-b15e-47bf-b183-7032d584753c', '', '', '', 10, '乌乌兔', 'dd', '', '### 概述\nd\n\n### 优缺点\nd\n\n### 装备\nd\n\n### 输出循环\nd', 'ability_animusdraw', 0, 1785401285, 1785401285, 1, 8, 4, 0, 0),
(52, '08e89449-2eb1-40cf-aebb-85745bdce653', '', '', '', 10, '朱马斯', '帕皮·桑切斯 100% 火烤', '', '### 概述\n继续努力', 'ABILITY_SEAL', 0, 1785427899, 1785427899, 2, 8, 0, 0, 0),
(53, 'a2487809-7a86-44c9-b756-f7d13a652453', '', '', '', 10, '阿莫斯', '阿莫斯的大佬构筑', '', '### 概述\n这个构筑是为了在全爆发下用狼和元素秒杀首领，我目前带狗崽子出来单体可以达到 12k+ DPS 持续 30 秒，除了爆发期，单体大约 3.6k DPS\n\n### 优缺点\n大爆发+ 没有真正的 AOE-', 'Ability_BackStab', 3, 1785430621, 1785430621, 2, 8, 0, 0, 0),
(54, 'edee3470-4fd5-43c3-8f1a-f2b1ceb8fb45', '', '', '', 10, '班布', '远程兽王猎', '', '### OVERVIEW\n远程兽王猎，曾经的龟龟已然落幕，但是兽王还在前行，推荐新人搞一套，敏捷暴击无脑冲就行了，2键输出，法力必选，全场景适用。蓝色RE提尔的救赎，强烈建议DPS都带一个，群拉很给力，极大增加了生存，其他也没的好的技能增伤可选。\n\n### MACROS\n/startattack\n/cast [mod: Alt] Life Tap\n/castsequence [@cursor] reset=10 Arcane Shot,Unrelenting Wrath,Frenzy Shot,Barbed Shot,Shredding Shot,Steady Shot,Multi-Shot\n/cast Kill Command', 'Ability_Druid_KingoftheJungle', 2, 1785431271, 1785480051, 2, 8, 1, 0, 4),
(55, '9bfdf096-9c50-4341-b7e0-56622ef46b90', '', '', '', 10, '吉姆摩根', '冰法 AOE/单体 法力风暴/RDF', '', '### 概述\n欢迎！！这是一个很棒的入门构筑，适合那些想要简单升级方式的人，而且你不需要任何秘术附魔。20 级后你可以挑选任何想加入循环的法术/技能。\n\n### 输出循环\n单体无脑寒冰箭\nAOE 3+ 无脑暴风雪\n\n### 消耗品\n在法力风暴中，确保在需要生命/法力时使用你的无尽法力风暴药水', 'Spell_Frost_IceStorm', 3, 1785443183, 1785443183, 1, 8, 3, 0, 0),
(56, 'dbf2d066-c1fb-4787-9849-85ddf0e6ffb3', '', '', '', 10, '阿拉克索', '泰坦之握 霜火 凛冬之风', '', '### 概述\n-属性顺序，（力量 - 法术强度 - 智力）              二元之道- 专精    -   -技能顺序 -邪恶攻击 x2- 熔岩扫击-旋风斩-风暴打击-邪恶攻击-凛冬之风。  所有技能都宏上顺劈斩，冰霜打击用于循环中的任何空档期，如果你漏了邪恶攻击或没从邪恶攻击获得双重连击点。   -     -主手火舌，副手石咬以获得双倍攻强    -    -提示--构筑可能会根据是否还有风暴打击的 RE 出现而变化，或者把嗜血换成冰霜顺劈。你可以把（怒焰顺劈）换成嗜血 RE，如果你的近战暴击几率不足以快速叠层。  - 未来的 RE - 巨大的 RE 升级会涉及能量回复或邪恶攻击消耗降低，以便更频繁地刷他\n\n### 优缺点\n你可以在没有泰坦之握的情况下运行这个构筑，但你可能需要在怒气生成上投入更多点数。在你获得足够好的武器来弥补物理伤害损失之前，你不应该切换到泰坦之握，英雄双手武器能让你很好地跳到泰坦之握。', 'Ability_Mage_ChilledToTheBone', 1, 1785447082, 1785447082, 2, 8, 0, 0, 1),
(57, '2b59c0de-6ace-4177-8ba3-285eb0db37f9', '', '', '', 10, '卡盖', '死亡骑士坦克 - 幽魂打击与灵魂链接', '', '### 概述\n这是我在史诗地下城中一直使用的坦克构筑。尚未完成，但我用它取得了如此大的成功（几乎不受到伤害），所以我想分享出来。\n\n基本思路是尽可能多地招架，让我的恶魔吸收尽可能多的伤害。\n\n技能选择说明：\n\n- 奴役恶魔而非虚空行者，因为我更喜欢 5% 伤害减免而不是 10% 物理减免。\n- 灵魂链接是固定 20% 伤害减免，很难拒绝。\n- 吞噬瘟疫算作死亡打击的疾病\n- 盗贼法术/天赋提供连击点，我们需要一种消耗它们的方式。切割对我们的攻击速度很好，恢复很烂但它是连击点倾泻。\n- 我喜欢旋风斩而不是血液沸腾，因为我想要血符文用于瘟疫\n- 冲锋在那里是因为我喜欢它。\n- 顺劈斩伤害很好，宏到一切。\n\n我找到的最好的恶魔是屈服的女士。\n\n秘术附魔不言自明，但也不完整。我需要做更多研究。\n\n我用主属性力量和二元之道测试过这个，二元之道伤害更高。但是，力量之路提供额外招架，既然这是我们关心的，我们就走力量之路。\n\n### 优缺点\n优点：\n\n- 大量被动伤害减免\n- 大多是 AOE 法术\n- 死亡打击提供良好的自我治疗\n\n缺点：\n\n- 你需要跟踪幽魂打击增益。\n- 如果你的恶魔死了，你会失去大量伤害减免。\n- 它不太花哨。\n\n### 装备\n你最想要的是护甲（冰霜灵气增加板甲护甲，天赋将护甲转化为伤害）。之后，招架为王。\n\n### 输出循环\n按键优先级为：\n\n- 幽魂打击（+10% 招架）\n- 疾病（如果瘟疫使者激活就用它，否则用冰霜之触/瘟疫打击，如果已经施放就用瘟疫）\n- 死亡打击\n- 还击\n- 奉献\n- 吞噬瘟疫（如果是首领）\n- 旋风斩\n- 切割\n- 恢复\n\n### 宏\n你想把顺劈斩宏到大多数法术，像这样：\n\n{HT}showtooltip Death Strike\n/cast Cleave\n/cast Death Strike\n\n### 备注\n如果你有任何建议，请分享。', 'ability_deathknight_necroticaura', 6, 1785450740, 1785451302, 2, 2, 0, 0, 1),
(58, 'a6bec70f-e12a-4b8c-a222-1ea26edaf751', '', '', '', 10, '提拉纳斯特罗斯', '双手冰霜死亡骑士 切割与冰霜 凛冬之风', '', '### 概述\n我的死亡骑士切割与冰霜 + 凛冬之风构筑的变体。修正了投入双持的问题，因为切割与冰霜依赖于使用双手武器。\n\n不幸的是，使其完全运作所需的冰霜死亡骑士天赋投入最终使得无法获得冰霜法师的冰霜之指 + 碎裂天赋。', 'Ability_Mage_ChilledToTheBone', 1, 1785451007, 1785451019, 1, 8, 1, 0, 0),
(59, 'fd9a0bd7-28a4-474b-8df3-cefbc18607de', '', '', '', 10, '阿西亚', '别用这个。垃圾', '', '### 概述\n不要使用', 'Interface\\Icons\\INV_Misc_QuestionMark', 0, 1785453390, 1785453390, 1, 8, 0, 0, 0),
(60, '040ecdc3-a4ee-4f6f-b1dc-5e3f9ba458ea', '', '', '', 10, '战鹰', '法力风暴 奥术师 AOE', '', '### 概述\n尝试将其作为升级构筑制作，遇到问题，这是 60 级的', 'ability_boss_fatescribe_rune5', 1, 1785460771, 1785460771, 2, 8, 3, 0, 0),
(61, 'e6e33fde-3183-4940-a9a1-851a8300d89b', '', '', '', 10, '战鹰', '奥术师 AOE 用于法力风暴', '', '### 概述\n惊人的 AOE\n\n### 优缺点\n优点 - AOE、DPS\n\n缺点 - 单人时是玻璃大炮，但 DPS 很快', 'ability_boss_fatescribe_rune4', 2, 1785463141, 1785463141, 1, 8, 3, 0, 0),
(62, '1cb813e0-db55-4744-92e9-74694834cd09', '', '', '', 10, '格雷弗林', '真言术：盾 牧师 大秘境', '', '### 概述\n这个构筑大量投入真言术：盾和愈合祷言。极好的治疗，瞬间顶上队友并且很快！\n\n### 优缺点\n优点：\n\n大治疗\n\n大量瞬发\n\n真言术：盾的大吸收\n\n缺点：\n\n老实说没找到任何缺点\n\n### 装备\n属性优先级 - \n\n智力 > 法术强度 > 精神 > 暴击\n\n### 备注\n如果你在这个构筑上挣扎，欢迎私信我！它对我非常有效', 'spell_holy_divinespirit', 1, 1785464542, 1785464542, 2, 4, 4, 0, 2),
(63, '471659d6-686c-4d0b-a16e-91b3ba2af1a7', '', '', '', 10, '马尼斯', '大死灵法师 冰封北方包', '', '### 概述\n他们用 36 个尼鲁布领主的灵液浇灌了这个。冷到他们会问你“去冰冠冰川怎么走？” 玩家，这会让你的心脏起搏器平线却仍然让你蹒跚行走。核弹级别的霜。心跳停止，死灵法师大麻。这东西上面有钻石，所以你知道霜花与忧郁草的比例是传奇的。一口这个？是的，这就是那种邪恶的盗墓冰川草。这直接来自诺森德。这就是复活了 Tupac 并且他回来复仇的东西。\n\n施工中\n\n### 备注\n给自己弄一只骷髅法师作为宠物。和水元素一样运作，但是永久的。', 'Ability_Mage_ChilledToTheBone', 0, 1785469175, 1785469175, 2, 8, 3, 0, 0),
(64, '11ab6e1b-6528-4d9d-ab42-a8a65274bba1', '', '', '', 10, '名望满级', '我的冰霜构筑，施工中', '', '### 概述\n我的冰霜构筑，施工中', 'ability_ardenweald_priest', 0, 1785469917, 1785469917, 2, 8, 3, 0, 0),
(65, 'e863b010-903d-45b0-9b29-9cde1df29a51', '', '', '', 10, 'Xdlol', '经典战士+', '', '### 概述\n这个构筑将经典战士升级体验转变为更快更爆炸的东西。你保留了战士标志性的重击近战玩法，但获得了内置风怒、强大的冷却叠加以及卓越的 AOE 伤害，让你可以轻松地连锁拉怪。\n\n这个构筑玩起来很直接，但奖励良好的冷却管理。让你的技能保持冷却，优先升级武器和力量，你就能以极小的空档期扫过任务和地下城内容。无论你是在对抗一个精英还是一打怪物，这个构筑都有工具从 1 级到 60 级高效处理。\n\n### 优缺点\n这个专精非常适合升级，提供巨额 AOE 和强大的单体伤害。感觉就像一个用了兴奋剂的经典战士，轻松撕碎怪群和首领。\n\n这个专精围绕有效使用你的冷却（见下方宏），和大多数构筑一样，它只会随着你升级并解锁更多天赋和装备而变得更强。\n\n### 装备\n升级时你最大的升级始终是你的武器。如果你使用传家宝，这就不是问题了，因为你可以舒适地穿整套到 60 级。\n\n力量是你的主属性，应始终是你的优先级。由于你的天赋和技能，你会自然获得大量暴击和急速，使力量成为你最有价值的属性。\n\n### 输出循环\n在 AOE 拉怪时，先冲锋进入怪群，然后使用旋风斩对所有附近敌人施加撕裂。接着使用长矛、龙吼和剑刃风暴。整个战斗中，按住顺劈斩并在技能冷却好时使用以最大化伤害。\n\n对于单体遭遇（如首领），先冲锋，然后旋风斩、死亡之愿和你的冷却宏（下方链接）。接着使用巨人打击、怒击和嗜血。\n\n起手后，循环嗜血和怒击，如果撕裂掉了就保持它。冷却好就使用巨人打击，每当怒气低时施放风暴打击以保持循环顺畅。\n\n### 宏\n{HT}showtooltip\n/cast Avatar\n/cast Skull Banner\n/cast Bloodbath\n/cast Warcry\n/cast Recklessness\n/cast Gurubashi Rage \n\n{HT}showtooltip\n/cast [@cursor] Champion\'s Spear\n\n### WEAKAURAS\n怒气 / 挥击计时器\n\n### 备注\n你本质上是一个内置风怒、强大冷却叠加和毁灭性 AOE 技能的经典战士。保持你的冷却滚动，不要让任何东西闲置，从一个怪群冲锋到另一个，旋转着穿过你路上的一切。', 'ability_warrior_innerrage', 0, 1785486790, 1785581552, 2, 8, 0, 0, 1),
(66, 'e3ef4781-0365-4e98-a759-3a92fc5867b6', '', '', '', 10, '摇头狂', '暗影盗贼（惩罚版本答案）', '', '### 概述\n近战盗贼/死亡骑士。高伤害爆发窗口，反施法者工具箱。\n\n在 1v1 或 2v2 环境中表现出色。不建议在战场中大量使用。\n\n下方有宏以简化循环。\n\n### 优缺点\n优点：\n+强大的反魔法防御\n+尚可的物理伤害防御\n+大量控制\n+大量近身技能\n+极高的爆发（假人测试 19 秒约 55k 伤害）\n+爆发窗口外非常可观的压制力\n+可宏化\n\n缺点：\n-高技巧上限\n-需要大量按键\n-宏并不总是那么灵活\n-没有免疫\n-没有饰品 + 被晕非常致命\n-主要是近战攻击\n-没有自我治疗\n-潜行很弱，必须考虑被发现\n\n### 装备\n敏捷+PvP 属性\n2 把匕首或 1 把主手匕首和 1 把副手剑\n\n### 输出循环\n先钓一个饰品，然后使用像肾击这样的控制。\n执行爆发宏或自己手动。\n大窗口：\n暗影步 + 伏击 6-7 次。\n除了可能需要再来一次眩晕外，不要把连击点花在任何其他东西上。只需无脑步+伏击\n\n普通暗影之舞的小窗口：\n普通控制 + 伏击和幽魂终结\n\n### 消耗品\n主手 燃烬冰川符文\n副手 毒药\n\n### 宏\n{HT}showtooltip [mod:shift] Ghostly Finish; Ambush\n/cast [mod:shift] Cold Blood\n/cast [mod:shift] Ghostly Finish\n/stopmacro [mod:shift]\n/cast Warcry\n/cast Shadow Blades\n/cast Shadowstep\n/castsequence reset=target/15 Forbidden Technique, Ambush, Ambush, Ambush, Ambush, Ambush, Ambush, Ambush, Ambush, Ambush\n\n\n\n在肾击后只需无脑按你的键位而不按 shift，最后按 shift 并无脑按同一个按钮。\n\n### WEAKAURAS\n伏击 WA，当你有可用的时候就会亮起。\n\n### 备注\n在何时以及如何施加压力方面高度可调。\n\n你可以减少你的暗影伤害以增加整体压制。但一般来说你有生存问题，你需要在他们杀死你之前杀死他们。\n\n任何改进请发消息。\n\n注意：目前冰霜灵气有 bug，你需要在退出潜行后每次手动使用它。你可以保持鲜血灵气，但它不如冰霜灵气好。\n\n如果有人能测试邪恶灵气可能更好。', 'Ability_Throw', 2, 1785494950, 1785497211, 3, 8, 1, 0, 3),
(67, '8039491b-146b-47df-86e7-ca2129a70714', '', '', '', 10, '加特福', '已更新 - 地下城顺劈怪物 大秘境 20 已完成', '', '### 概述\n更新：[正在更新中]\n\n这个构筑已经通关并刷到史诗+20。用简单循环打出顶级 DPS。\n\n--> 如果你有任何问题随时发消息 <--\n\n移动了一些天赋；\n\n- 撕裂打击（24% 护甲穿透）<-- 对小怪群疯狂 OP\n- 优化了 % 伤害天赋\n- 9 点精准天赋\n- 0 命中天赋，因为我现在从装备上有了。如果你缺命中，你可以从撕裂打击拿点数放入热诚（狂暴姿态下 1% 命中/1% 暴击）\n- 添加嗜血作为填充（1 点重置机制感觉很好）\n- 从一键宏中移除化身并作为次要冷却处理。在小怪或死亡之愿/复仇之怒之间使用，因为它们仍然叠加。\n- 添加破甲\n- 添加骷髅旗帜（大秘境的 OP 冷却）\n\n这个构筑现在带来巨大团队增益 -> 10% 攻强 / 5% 暴击 / 王者 / 战斗怒吼\n\n新循环：\n\n通过死亡印记和使用切割维持 46% 攻速的切割。如果在冷却中，你可以从邪恶攻击连击点触发切割。\n\nAOE -> 扫击、神圣风暴、旋风斩、嗜血、审判、邪恶攻击 \n\n单体 -> 扫击、神圣风暴、嗜血、审判、旋风斩、邪恶攻击\n\n如果你有连击点，你可以使用破甲，或者如果切割持续时间已满，使用死亡印记接 5 点破甲以造成超强首领伤害撕裂。\n\n\n主要技能：\n\n- 扫击\n- 神圣风暴\n- 旋风斩\n- 顺劈斩\n- 嗜血\n- 审判\n- 邪恶攻击 \n\n次要：\n\n- 菌丝戒指 \n- 死亡印记\n- 切割\n\n主要 DPS 冷却：\n\n- 化身\n- 复仇之怒\n- 死亡之愿 \n\n这个构筑将依赖这些互动：\n\n- 顺劈斩（宏到所有技能并无脑按）\n- 扫击（触发熔火之怒造成巨额 AOE 伤害）\n- 神圣风暴（有时在神圣伤害时重置）\n- 死亡印记（提供 5 个连击点）\n- 切割（在击杀时通过盗贼天赋刷新）\n\n### 优缺点\n|cff1aff1a+少按键大伤害|r\n\n### 装备\n- 8% 命中\n- 26 精准评级\n\n\n命中 -> 精准 -> 力量 -> 攻击强度 -> 暴击 -> 护甲穿透 -> 急速 \n\n你应尽可能避免装备上的急速，它是低优先级且对我们几乎是死属性\n\n### 输出循环\n扫击 -> 神圣风暴 -> 旋风斩 -> 嗜血 -> 审判 -> 邪恶攻击\n\n优先扫击以清理 AOE 和神圣风暴重置。\n\n将光缚顺劈宏到你的所有技能，这是免费伤害\n\n### 消耗品\n我们热爱力量和攻击强度\n\n### 宏\n/cast lava sweep\n/startattack\n/cast Lightbound Cleave(Rank 5)\n\n/cast whirlwind\n/cast Lightbound Cleave(Rank 5)\n/startattack\n\n/cast divine storm\n/startattack\n/cast Lightbound Cleave(Rank 5)\n\n/cast judgement of wisdom\n/startattack\n/cast lightbound cleave(Rank 5)\n\nAIO CD\n\n/cast death wish\n/cast avenging wrath\n/use Bloodbath(Rank 3)\n/cast blood fury\n/cast Bloodbath\n\n### 备注\n随意根据史诗+需要更改一些天赋和技能\n\n考虑踢、晕、自由、驱散等\n\n或者如果你想添加更多伤害天赋', 'SPELL_HOLY_AVENGINEWRATH', 15, 1785496456, 1786493369, 2, 8, 0, 0, 0),
(68, '638cccc5-7b58-4086-8815-0a926c3b1d19', '', '', '', 10, '维里塔斯', '冰霜游侠', '', '### 概述\n构建一个冰霜游侠治疗……让我们看看这能不能行。', 'ability_ardenweald_hunter', 3, 1785498684, 1785498684, 1, 4, 4, 0, 0),
(69, 'a483dcaf-0b01-467b-955f-5504eba84727', '', '', '', 10, '塞亚', '冰霜电击 伤害', '', '### 概述\n当前冰霜电击构筑。简单且大量 AOE 和单体伤害。成为地下城中的顶级伤害！试试看，用附魔或天赋改进它！这是我刚满 60 时找到的附魔。只是想分享出来让你们也看看！\n\n就走经典法师属性优先级。\n\n### 优缺点\n简单构筑，大量伤害。', 'ability_bastion_hunter', 1, 1785502628, 1785502762, 2, 8, 3, 0, 0),
(70, '99771807-3cbe-4429-8401-40c706d49d72', '', '', '', 10, '阿莫斯', '阿莫斯 狼 核弹 2.2', '', '### 概述\n和旧的一样，但这个只是力量，所以……如果你只走力量装备/力量主属性，狼基本上多造成 25% 伤害', 'ability_worgen_darkflight', 0, 1785518492, 1785518492, 2, 8, 0, 0, 0),
(71, 'c1ae0a02-530e-4376-9b60-4c131a1d5d2c', '', '', '', 10, '芬茨', '暗影熊', '', '### 概述\nqwerty', 'Ability_Ambush', 2, 1785526937, 1785526937, 2, 8, 0, 0, 0),
(72, '428bbadc-54dc-41ed-b2af-41dbec5f67d4', '', '', '', 10, '提拉纳斯特罗斯', '提尔的升级 AOE 惩戒', '', '### 概述\n尝试制作一个不那么耗蓝的 AOE 惩戒圣骑士。大部分成功，但如果缺少奥术专注触发和补满触发，有可能耗尽法力。\n\n注意：高度依赖 3 个核心秘术附魔以获得最高伤害输出。\n1. 审判时刻\n2. 圣殿打击\n3. 圣化武器\n\n建议使用传家宝并运行法力风暴升级。专注于 AOE 的构筑，受益于大量目标，但在单体伤害和自我维持方面略有不足。\n\n以火焰冲击开场，在你开始升级时帮助打碎敌人。有助于标记和远程拉怪。但在青少年等级可以放弃。\n\n查看循环和宏部分。\n\n在团队内容中使用命令圣印，如果需要法力回复就使用智慧圣印。\n在团队中使用暗影抗性光环，否则使用专注光环，这样怪物对圣殿打击的击退更少。\n\n### 优缺点\n优点：\n+ 高 AOE 输出\n+ 从 40 级开始不错的爆发\n\n缺点：\n- 平庸的单体输出\n- 缺乏自我维持。在较高等级单人任务时可能挣扎。\n- 耗蓝。奥术专注天赋有帮助，但只是推迟了不可避免的法力耗尽。\n\n在法力风暴中畅饮无尽法力风暴药水以回复法力。你会偶尔需要它。\n\n### 装备\n推荐：\n冠军传家宝\n|cffe6cc80|Hitem:1339124:0:0:0:0:0:0:0:50|h[Champion Herod\'s Helmet]|h|r\n|cffe6cc80|Hitem:1642950:0:0:0:0:0:0:0:50|h[Champion Herod\'s Shoulder]|h|r\n|cffe6cc80|Hitem:1648677:0:0:0:0:0:0:0:50|h[Champion\'s Deathdealer Breastplate]|h|r\n|cffe6cc80|Hitem:1339096:0:0:0:0:0:0:0:50|h[Champion Herod\'s Belt]|h|r\n|cffe6cc80|Hitem:1339117:0:0:0:0:0:0:0:50|h[Champion Herod\'s Legguards]|h|r\n|cffe6cc80|Hitem:1339103:0:0:0:0:0:0:0:50|h[Champion Herod\'s Boots]|h|r\n|cffe6cc80|Hitem:1339110:0:0:0:0:0:0:0:50|h[Champion Herod\'s Bracers]|h|r\n|cffe6cc80|Hitem:1339131:0:0:0:0:0:0:0:50|h[Champion Herod\'s Gloves]|h|r\n|cffe6cc80|Hitem:1339084:0:0:0:0:0:0:0:50|h[Champion\'s Deathdealer Cloak]|h|r\n\n任何双手近战传家宝\n任何传家宝戒指、项链、饰品。\n\n### 输出循环\n单体：\n|cff71d5ff|Hspell:10312|h[Exorcism]|h|r 配合战争艺术触发（瞬发）\n如果目标生命值 20% 或以下：|cff71d5ff|Hspell:24275|h[Hammer of Wrath]|h|r + |cff71d5ff|Hspell:20661|h[Execute]|h|r x2\n保持 |cff71d5ff|Hspell:20922|h[Consecration]|h|r\n|cff71d5ff|Hspell:53408|h[Judgement of Wisdom]|h|r\n|cff71d5ff|Hspell:53385|h[Divine Storm]|h|r\n|cff71d5ff|Hspell:278742|h[Templar\'s Slash]|h|r\n|cff71d5ff|Hspell:35395|h[Crusader Strike]|h|r\n填充：\n|cff71d5ff|Hspell:11580|h[Thunder Clap]|h|r / |cff71d5ff|Hspell:907424|h[Dawn Smash]|h|r\n\nAOE：\n|cff71d5ff|Hspell:282984|h[Hour of Judgement]|h|r\n|cff71d5ff|Hspell:954903|h[Light\'s Hammer]|h|r\n|cff71d5ff|Hspell:2814|h[Holy Wrath]|h|r\n保持 |cff71d5ff|Hspell:20922|h[Consecration]|h|r\n|cff71d5ff|Hspell:278742|h[Templar\'s Slash]|h|r（它有 3 层充能，我建议在奉献、雷霆一击和旋风斩之间穿插一次施放）\n|cff71d5ff|Hspell:11580|h[Thunder Clap]|h|r / |cff71d5ff|Hspell:907424|h[Dawn Smash]|h|r\n|cff71d5ff|Hspell:1680|h[Whirlwind]|h|r / 旋转之光\n|cff71d5ff|Hspell:11608|h[Cleave]|h|r / |cff71d5ff|Hspell:907302|h[Lightbound Cleave]|h|r\n\n### 宏\n{HT}showtooltip\n/castsequence reset=7 Judgement of Wisdom, Crusader Strike\n/cast Heroic Strike\n/startattack\n\nAOE 循环：\n{HT}showtooltip\n/castsequence reset=combat/8 Consecration, Templar Slash, Thunderclap, Templar Slash, Whirlwind, Templar Slash\n/cast Cleave\n/startattack\n\n注意：如果已知则用秘术附魔替换基础技能（|cff71d5ff|Hspell:907424|h[Dawn Smash]|h|r 换 |cff71d5ff|Hspell:11580|h[Thunder Clap]|h|r，旋转之光 换 |cff71d5ff|Hspell:1680|h[Whirlwind]|h|r，|cff71d5ff|Hspell:907303|h[Lightbound Cleave]|h|r 换 |cff71d5ff|Hspell:11609|h[Cleave]|h|r）\n\nAOE 冷却：\n{HT}showtooltip\n/castsequence reset=combat/30 [@cursor] Light\'s Hammer, Holy Wrath\n\n燃烧阶段（生命值 20% 或以下）\n{HT}showtooltip\n/castsequence reset=combat/3 Execute, Hammer of Wrath, Execute\n\n爆发（配合法力风暴药水）\n{HT}showtooltip\n/cast Avenging Wrath\n/cast Sweeping Strkes\n/cast Manastorm: Reflex Booster\n\n### 备注\n有了战争艺术天赋和神圣重置秘术附魔，驱邪术和神圣风暴技能将可在不同间隔施放，因此不适合放入一键循环。\n\n如果你有 WeakAuras，你可以为战争艺术和奥术专注设置追踪器，告诉你施放驱邪术的最佳时机，使其成为免费的瞬发施放。', 'SPELL_HOLY_AVENGINEWRATH', 3, 1785538197, 1786512444, 1, 8, 1, 0, 1),
(73, '863f7b56-e106-4f50-b9ee-5c59e085ee25', '', '', '', 10, '耶勒米哈斯', '冰奶', '', '### OVERVIEW\n输出奶，刚需35紫色魔咒冰冷医师', 'ability_ardenweald_paladin_winter', 1, 1785544471, 1785544471, 2, 4, 4, 0, 0),
(74, '02a060fe-d52c-4c15-a21b-ec809fa8516c', '', '', '', 10, '辛古拉里昂', '提尔的暗影术士升级构筑', '', '### 概述\n一个专注于暗影箭的术士构筑，利用夜幕天赋实现瞬发暗影箭，以及后期的腐蚀之种。\n在后期等级转向专注于野生小鬼，因为野生小鬼疯狂强。\n\n这个构筑非常耗蓝。建议通过法力风暴升级。否则，准备好定期喝水。魔法食物、水和茶点在单人内容和地下城中大大帮助回复。\n\n你可以追踪奥术专注/清晰施法以高效使用高消耗法术并最小化法力消耗。\n\n### 优缺点\n|cff1aff1a+高单体和 AOE 伤害潜力|r\n+一些控制选项\n+仆从。虚空行者可以轻松坦单人内容。\n+ 使用虚空之裔 + 冰冷血脉 + 灵魂收割打出不错的爆发\n\n-法力吞噬者。在长时间战斗/首领战中可能耗尽法力。\n\n### 输出循环\n单人：\n用寒冰箭拉怪（宏上 /petattack）\n施加 腐蚀术\n古尔丹之手召唤野生小鬼\n无脑暗影箭\n暗影之怒 / 冰霜新星 控制靠近的敌人。\n亡者行军造成爆发伤害。瞄准墙壁或悬崖。如果你在开阔区域召唤亡灵，它们可能会游荡很远并吸引更多东西。\n\n地下城/法力风暴中的 AOE：\n亡者行军和辛达苟萨之息作为自由施法 AOE\n\n低等级时，暗影炮击和引导火焰之雨。\n\n高等级时：\n古尔丹之手\n暗影炮击\n使用腐蚀之种，交替目标。在法力风暴中，每隔一个腐蚀之种由于法力风暴急速提升会瞬发。\n暗影之怒用于一些控制。\n\n首领循环：\nDOT 序列：腐蚀术 > 暗言术：痛 > 吞噬瘟疫 > 元素诅咒\n爆发冷却：灵魂收割、冰冷血脉\n地狱火\n古尔丹之手\n无脑暗影箭\n重新施加 DOT 并冷却好就使用古尔丹之手\n如果首领靠近或靠着墙，面向墙壁，首领在你和墙之间，使用亡者行军。\n\n### 宏\nDOT 序列：\n{HT}showtooltip\n/castsequence Corruption, Shadow Word: Pain, Devouring Plague, Curse of the Elements\n/petattack\n\n爆发：\n{HT}showtooltip\n/cast Soul Harvest\n/cast Icy Veins\n\n其他：\n{HT}showtooltip\n/cast [@cursor] Shadowfury', 'ability_demonhunter_netherbond', 0, 1785554778, 1786307054, 1, 8, 3, 0, 0),
(75, '3b2279cd-e94f-4738-8939-e638a9c08e30', '', '', '', 10, '卡拉', 'EZ', '', '### 概述\nEZ', 'ability_deathknight_necroticaura', 1, 1785557079, 1785557117, 1, 8, 1, 0, 0);
INSERT INTO `coa_build_creator` (`entry`, `id`, `leveling_id`, `pve_id`, `pvp_id`, `class`, `author`, `name`, `subtext`, `description`, `icon`, `upvotes`, `created`, `updated`, `category`, `roles`, `primary_stat`, `flags`, `difficulty`) VALUES
(76, 'ac7af313-6a2f-494e-b768-4daa54c32068', '', '', '', 10, '黑暗法师', '丛林游侠', '', '### 概述\n施工中', 'Ability_Ambush', 0, 1785560356, 1785560441, 2, 4, 4, 0, 0),
(77, '56d76f98-43bf-49bb-8f1f-802966c94894', '', '', '', 10, '拉尼', '元素领袖 施工中', '', '### 概述\n施工中', 'Spell_Azzarminigames_silence', 0, 1785578592, 1785578592, 1, 8, 0, 0, 0),
(78, 'aa510e0b-fab0-4a92-9373-7726bc7f6b2b', '', '', '', 10, '好咒', '巫毒（施工中）', '', '### 概述\n智力/精神 DPS/辅助构筑', 'ability_racial_wardoftheloaarcane', 0, 1785585901, 1785585901, 2, 8, 3, 0, 2),
(79, '7de9eb5c-5736-447b-9fd0-d9729c72e679', '', '', '', 10, '布雷泽', '布雷兹 - 暗影大师', '', '### 概述\nDOT 再加更多 DOT', 'ability_priest_voidentropy', 1, 1785592820, 1785592820, 2, 8, 3, 0, 0),
(80, '8c8461ab-438c-4a7a-8ad7-3d74d2921d46', '', '', '', 10, '流放者', '测试', '', '### 概述\n测试。', 'ability_skyreach_empowered', 0, 1785593758, 1785593878, 2, 8, 0, 0, 0),
(81, '39f689ab-df35-4106-9d2b-ef0df097fe96', '', '', '', 10, '穆尔基', '蘑菇 DOT 施工中', '', '### 概述\n施工中，请勿使用', 'INV_Misc_QuestionMark', 0, 1785597211, 1785597211, 1, 8, 3, 0, 0),
(82, '9a1ef287-7da6-487c-85a7-8eb98206afaf', '', '', '', 10, '遥', '双黎明 - 邪恶攻击刷子', '', '### 概述\n用黎明打击和邪恶连击双重压制。\n\n按 1。赢。\n\n快速名望重置。', 'ability_bastion_warrior', 2, 1785597503, 1785597503, 1, 8, 0, 0, 0),
(83, '2f4755d9-d8e6-4d70-91d0-d478d39ac92e', '', '', '', 10, '梅杜扎', '圣殿骑士（测试）', '', '### 概述\n测试', 'Ability_Warrior_VictoryRush', 0, 1785618595, 1785618595, 1, 8, 3, 0, 0),
(84, '16eecadf-7e77-4647-9da1-d4e7fc2ef9ae', '', '', '', 10, '兹克拉特', '肮脏的圣骑士', '', '### 概述\n非常搞笑且肮脏的刷子圣骑士。\n对地下城来说 AOE 伤害尚可。\n\n智慧祝福提供法力 --（但如果其他人使用智慧就换成王者祝福）。\n命令圣印始终开启 --（紧急回蓝 - 切换到智慧圣印）。\n恶魔护甲始终开启。\n凛冬号角始终开启。\n两把武器都附魔圣化武器。\n保持邪恶灵气。\n优先虔诚光环。\n\n冰霜之触保持冰霜之爪增益。\n横扫打击冷却好就用。\n血浴冷却好就用。\n龙吼冷却好就用。\n王者之锤冷却好就用。\n死亡与腐朽冷却好就用。\n奉献冷却好就用。\n神圣风暴冷却好就用。\n智慧审判冷却好就用。\n邪能顺劈冷却好就用。\n旋风斩冷却好就用。\n始终光缚顺劈。\n\n按需使用 DPS 冷却。\n\n重新分配天赋以达到命中上限。', 'Ability_Paladin_RighteousVengeance', 0, 1785624946, 1785625148, 2, 8, 0, 0, 0),
(85, 'e04e5bdb-5a28-4254-bedf-97370524621b', '', '', '', 10, '艾尔索恩', '血色圣骑士', '', '### 概述\n血色圣骑士利用圣骑士、牧师和战士天赋树中的神圣、暗影和物理攻击。理念是在法力和怒气消耗技能之间取得平衡，让你永不缺乏选择。主要是一个有趣且易于使用的构筑，拥有各种 AOE、单体和 DOT 伤害技能。\n\n### 优缺点\n万金油，拥有不错的单体选项和平均的 AOE 天赋。', 'ability_paladin_blindinglight', 0, 1785630808, 1785630808, 2, 8, 0, 0, 1),
(86, '19a07e51-fc6f-47ab-bb08-9a953fedffd4', '', '', '', 10, '格里兹', '基础火焰', '', '### 概述\n超级基础的火焰施法者', 'ability_deathwing_grasping_tendrils', 0, 1785634074, 1785634093, 2, 8, 3, 0, 0),
(87, 'd5ad5d81-7d1a-4fcf-b471-333e9c9c1ceb', '', '', '', 10, '格里兹', '大暗影', '', '### 概述\n大暗影伤害', 'ability_socererking_forcenova', 0, 1785635740, 1785635740, 2, 8, 3, 0, 0),
(88, 'd9045fe0-eca2-4744-bbb0-23c55bb8e827', '', '', '', 10, '纳克斯', '野兽与匕首', '', '### 概述\n剖腹、深度创伤和强化宠物', 'Ability_Hunter_Invigeration', 2, 1785670183, 1785670183, 1, 8, 1, 0, 0),
(89, 'b862a423-faa2-4b90-a985-8448878e458a', '', '', '', 10, '战鹰', '惩戒死亡骑士混合', '', '### 概述\n重度惩戒配混合死亡骑士，用于强大的单人、法力风暴、团本 DPS。\n\n### 优缺点\n优点 - 大量自我治疗和 AOE', 'Ability_Paladin_RighteousVengeance', 0, 1785670833, 1785670833, 2, 8, 0, 0, 0),
(90, '521c507e-6c0d-4546-82e1-245b1c1e7871', '', '', '', 10, '腐肢', '施工中', '', '### 概述\n施工中', 'Ability_Creature_Cursed_02', 0, 1785681137, 1785681137, 1, 8, 0, 0, 0),
(91, '6b379363-3f5c-4825-862b-b143fca7cd03', '', '', '', 10, '战鹰', '死亡惩戒骑士', '', '### 概述\n重度惩戒配死亡骑士技能。主要用于单人、法力风暴和地下城跑图。', 'ability_paladin_gaurdedbythelight', 2, 1785683171, 1785683171, 1, 8, 0, 0, 0),
(92, '06905f25-148f-4603-afdf-8f47e4aa56ec', '', '', '', 10, '费雷尼', '二元之道 火焰战士 烈焰打击顺劈', '', '### 概述\n二元之道双持混合近战/法师，使用匕首、顺劈、热 streak 和火starter造成强大的单体和大型 AOE。\n\n### 宏\n顺劈宏到一切\n\n{HT}showtooltip\n/startattack\n/cast Judgement of Wisdom\n/cast !Flamebound Cleave\n\n{HT}showtooltip\n/startattack\n/cast Fire Blast\n/cast !Flamebound Cleave\n\n{HT}showtooltip \n/startattack\n/cast Pyroblast\n/cast !Flamebound Cleave\n\n{HT}showtooltip \n/startattack\n/cast [@cursor] Flamestrike\n/cast !Flamebound Cleave\n\n{HT}showtooltip \n/startattack\n/cast Dragon\'s Breath\n/cast !Flamebound Cleave\n\n{HT}showtooltip\n/startattack\n/cast Lava Lash\n/cast !Flamebound Cleave\n\n{HT}showtooltip \n/startattack\n/cast Controlled Blast\n/cast !Flamebound Cleave\n\n{HT}showtooltip \n/startattack\n/cast [@cursor] Meteor\n/cast !Flamebound Cleave\n\n{HT}showtooltip \n/startattack\n/cast [@cursor] Capacitor Totem\n/cast !Flamebound Cleave\n\n{HT}showtooltip \n/startattack\n/cast Fire Elemental Totem\n/cast !Flamebound Cleave\n\n{HT}showtooltip \n/startattack\n/cast Cremation\n/cast !Flamebound Cleave\n\n{HT}showtooltip \n/startattack\n/cast Living Bomb\n/cast !Flamebound Cleave\n\n{HT}showtooltip \n/startattack\n/cast Combustion\n/cast Warcry\n/cast Berserking(Racial)\n/cast !Flamebound Cleave', 'Interface\\Icons\\INV_Misc_QuestionMark', 0, 1785683223, 1785684627, 2, 8, 0, 0, 2),
(93, '7857931d-b81e-4c3b-930d-19806769d3e0', '', '', '', 10, '艾拉', '暗影死亡骑士', '', '### 概述\n二元之道。用力量/智力装备。优先暴击以触发游荡瘟疫。', 'Interface\\Icons\\INV_Misc_QuestionMark', 1, 1785683484, 1785683484, 2, 8, 0, 0, 2),
(94, 'e12be89d-3179-4b52-9f37-f19968aba2bb', '', '', '', 10, '山羊看', '治疗链', '', '### 优缺点\nasd\n\n### 装备\nasd', 'Interface\\Icons\\INV_Misc_QuestionMark', 0, 1785690990, 1785690990, 1, 4, 0, 0, 0),
